import {sizePosition} from './risk-model.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const stockNames={QS:'QuantumScape',CAT:'Caterpillar',RUN:'Sunrun',PTON:'Peloton',NET:'Cloudflare',FSLR:'First Solar',NCLH:'Norwegian Cruise Line',NIO:'NIO',UAL:'United Airlines',AMD:'AMD',RKT:'Rocket Companies',FUTU:'Futu Holdings',SOFI:'SoFi',AFRM:'Affirm',PLTR:'Palantir',MU:'Micron',RIOT:'Riot Platforms',CVNA:'Carvana',CLF:'Cleveland-Cliffs',TSLA:'Tesla',MRNA:'Moderna'};
const periods = ['1','6','12'];

function percentile(rows, row, key, lowerIsBetter = false) {
  if (!Number.isFinite(row[key])) return 0;
  const comparable = rows.filter(other => Number.isFinite(other[key]));
  const wins = comparable.filter(other => lowerIsBetter ? row[key] < other[key] : row[key] > other[key]).length;
  const ties = comparable.filter(other => other !== row && other[key] === row[key]).length;
  return comparable.length > 1 ? (wins + ties / 2) / (comparable.length - 1) : 0.5;
}

export function candidates(rows, horizon, tolerance) {
  const window = horizon === 'Menos de 1 año' ? '1' : horizon === '1 a 3 años' ? '6' : '12';
  const riskWeight = tolerance === 'Más de 15%' ? 0.25 : tolerance === 'Hasta 15%' ? 0.40 : 0.55;
  const eligible = rows.filter(row => Object.hasOwn(stockNames,row.ticker) && row.price > 0 && Number.isFinite(row[window]));
  return eligible.map(row => {
    const returnScore = periods.reduce((sum, period) => sum + percentile(eligible,row,period) * (period === window ? 0.6 : 0.2),0);
    const score = returnScore * (1-riskWeight) + percentile(eligible,row,'movement',true) * riskWeight;
    return {...row,window,score};
  }).sort((a,b) => b.score-a.score || a.ticker.localeCompare(b.ticker)).slice(0,6);
}
export function allocation(capital,r,currency){if(!Number.isFinite(capital)||capital<=0)return null;const usable=r?.currency===currency?r:{};const invested=Number.isFinite(usable.invested)&&usable.invested>=0?usable.invested:0;if(invested>capital)return null;const result=sizePosition(capital,usable),simulated=result.error?0:result.allocation;return {invested,simulated,available:Math.max(0,capital-invested-simulated),capital,hasSimulation:!result.error};}
export function distributionPanel(state){const p=state.profile,a=allocation(p.capital,state.risk,p.currency),fmt=n=>`${n.toLocaleString('es-MX',{maximumFractionDigits:0})} ${esc(p.currency)}`;if(!a)return `<section class="card" style="margin:20px 0"><h2>Distribución de tu capital (simulación)</h2><p class="muted">Completa tu diagnóstico y revisa el capital comprometido para visualizar su distribución.</p></section>`;const first=a.invested/a.capital*100,second=first+a.simulated/a.capital*100;return `<section class="card allocation-card"><div><div class="eyebrow">DISTRIBUCIÓN DEL CAPITAL</div><h2>Distribución de tu capital (simulación)</h2><p class="muted">La simulación muestra una posible distribución. No representa operaciones ejecutadas.</p><div class="chart-legend">${[['#7058b8','Ya comprometido',a.invested],['#b19bd7','Nueva posición simulada',a.simulated],['#e7e9dc','Sin asignar',a.available]].map(([c,label,n])=>`<div><i style="background:${c}"></i><span>${label}</span><b>${fmt(n)}</b><small>${(n/a.capital*100).toFixed(1)}%</small></div>`).join('')}</div><p class="chart-note">La reserva de emergencia (${Number.isFinite(p.savings)?fmt(p.savings):'pendiente'}) queda separada. El presupuesto de pérdida no se suma al capital. ${a.hasSimulation?'Se usa la última simulación guardada.':'Guarda una simulación válida para visualizar una nueva posición.'}</p></div><div class="donut" role="img" aria-label="Distribución: ${a.invested} comprometidos, ${a.simulated} simulados y ${a.available} sin asignar, en ${esc(p.currency)}" style="background:conic-gradient(#7058b8 0% ${first}%,#b19bd7 ${first}% ${second}%,#e7e9dc ${second}% 100%)"><div><small>CAPITAL TOTAL</small><strong>${fmt(a.capital)}</strong></div></div></section>`;}
export function candidatesPanel(rows,state,d){const list=candidates(rows,state.profile.horizon,state.profile.tolerance),period=list[0]?.window||'12';return `<section class="card" id="candidate-panel" style="margin:20px 0"><div class="section-head"><div><div class="eyebrow">OPORTUNIDADES · STOCKEX</div><h2>Acciones para evaluar en tu estrategia</h2></div><span class="pill purple">Archivo · 29 oct 2026 · No son precios en vivo</span></div><p class="muted">${d?`Tu objetivo: ${esc(state.profile.goal)}. Horizonte: ${esc(state.profile.horizon)}.`:'Completa el diagnóstico para añadir contexto personal.'}</p><div class="notice">${d?.reasons.length?'Tu diagnóstico tiene prioridades pendientes. ':''}El rendimiento pasado no predice el futuro. La selección combina rendimientos históricos y movimiento diario según tu horizonte y tolerancia. Evalúa cada acción antes de decidir.</div><p class="chart-note">Se comparan los rendimientos a 1, 6 y 12 meses. La ventana de ${period} ${period==='1'?'mes':'meses'} recibe el mayor peso entre los rendimientos. Una tolerancia menor da más peso al movimiento diario bajo. Si falta un dato, esa métrica no aporta al puntaje.</p><div class="candidate-grid">${list.map(r=>`<article class="candidate"><div class="section-head"><strong>${esc(r.ticker)}</strong><span class="${r[period]>=0?'up':'down'}">${r[period]>0?'+':''}${r[period].toFixed(1)}%</span></div><h3>${esc(stockNames[r.ticker])}</h3><p>Cierre del archivo: <b>${r.price.toFixed(2)} USD</b></p><p class="chart-note">1m: ${Number.isFinite(r['1'])?r['1'].toFixed(1)+'%':'—'} · 6m: ${Number.isFinite(r['6'])?r['6'].toFixed(1)+'%':'—'} · 12m: ${Number.isFinite(r['12'])?r['12'].toFixed(1)+'%':'—'}</p><p class="chart-note">Periodo de referencia: ${period} ${period==='1'?'mes':'meses'} al 29 oct 2026. Rango de precios mínimo–máximo: sin datos en el archivo.</p><span class="pill">${Number.isFinite(r.movement)?`Riesgo por movimiento histórico ${r.movement>=3?'alto':r.movement>=1.5?'medio':'bajo'} · ${r.movement.toFixed(2)}% diario medio`:'Movimiento histórico sin datos'}</span><button class="secondary" data-analyze="${esc(r.ticker)}">${d?'Evaluar esta acción ↗':'Completar diagnóstico ↗'}</button></article>`).join('')||'<p class="muted">Cargando los datos históricos de stockEX…</p>'}</div><p class="chart-note" style="margin-top:16px">Al seleccionar una acción se conserva su símbolo. La entrada, el stop y los costos requieren datos vigentes confirmados; no se inventan a partir del ranking.</p></section>`;}
